def sha(b):return hashlib.sha256(b).hexdigest().upper()
def log(a,b,c,d):
 with (p/'changes.csv').open('a',encoding='utf-8',newline='') as f:csv.writer(f).writerow([now,p.name,a,b,c,d])
def read(rel):return (root/rel).read_text(encoding='utf-8-sig')
def write(rel,text):
 f=root/rel;before=f.read_bytes() if f.exists() else b'';after=text.replace('\r\n','\n').encode();log('CLOSE-DRYRUN',sha(before) if before else 'ABSENT',sha(after),rel);f.write_bytes(after);assert f.read_bytes()==after;changed[rel]=sha(after);log('CLOSE',sha(before) if before else 'ABSENT',sha(after),'PASS readback '+rel)
def replace(s,a,b):
 assert s.count(a)==1,a[:90]
 return s.replace(a,b,1)
